import json,re,xml.etree.ElementTree as ET
from collections import Counter
s=json.load(open('source.json')); a=json.load(open('answer.json'))
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
assert len(a)==len(s)==10
for old,new in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert new[k]==old[k],(old['number'],k)
 assert set(new)=={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status'}
 assert new['status']=='rewrite_draft' and new['proposed_xml'] and new['proposed_xml']"'!=old['"'source_xml'].strip()
 root=ET.fromstring('<root>'+new['proposed_xml']+'</root>')
 for el in root.iter():
  if el is root: continue
  assert el.tag in allowed,el.tag
  for k,v in el.attrib.items(): assert k in {'rowspan','colspan'} and v.isdigit()
 def plain(x): return ''.join(ET.fromstring('<root>'+x+'</root>').itertext())
 def nums(x): return Counter(re.findall(r'\\d+(?:[,.]\\d+)?',plain(x)))
 on,nn=nums(old['source_xml']),nums(new['proposed_xml'])
 oc,nc=len(re.findall('<p(?:>| )',old['source_xml'])),len(root.findall('p'))
 print(old['number'],'paragraphs',oc,nc,'numeric removed',dict(on-nn),'numeric added',dict(nn-on),'tables',old['source_xml'].count('<table'),new['proposed_xml'].count('<table'))
print('VALID JSON / IDENTIFIERS / STATUS / XML')
PY"

